/*
 * prog53_dfs_cycle – reproduced from the analysed binary
 *
 * The original program expects an even number of command‑line arguments
 * (after the program name).  Each pair of arguments represents a directed
 * edge  src -> dst  of a graph whose vertices are numbered 0 … 7.
 *
 *   ./prog53_dfs_cycle 0 1 1 2 2 0
 *
 * builds the adjacency matrix, runs a depth‑first search with the classic
 * three‑colour scheme (0 = unvisited, 1 = visiting, 2 = visited) and
 * reports whether the directed graph contains a cycle.
 *
 * If any of the following conditions hold the program prints
 *   INVALID_INPUT
 * and exits with status 1:
 *   • the number of arguments (excluding the program name) is not even,
 *   • any vertex number is outside the range 0 … 7,
 *   • an argument cannot be parsed as an integer.
 *
 * Otherwise it prints either
 *   CYCLE   – if a directed cycle exists,
 *   ACYCLIC – if the graph is acyclic.
 *
 * The implementation below follows the logic of the original binary
 * but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8

static int  adj[MAXV][MAXV];   /* adjacency matrix */
static int  color[MAXV];      /* 0 = unvisited, 1 = visiting, 2 = visited */
static bool found_cycle = false;

/* Depth‑first search that sets `found_cycle` when a back‑edge is seen. */
static void dfs(int v)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    color[v] = 1;                  /* mark as visiting */

    for (int w = 0; w < MAXV; ++w) {
        if (!adj[v][w])            /* no edge v→w */
            continue;

        if (color[w] == 0) {      /* unvisited vertex */
            dfs(w);
            if (found_cycle)      /* propagate early exit */
                return;
        } else if (color[w] == 1) {   /* back‑edge → cycle */
            found_cycle = true;
            return;
        }
        /* colour 2 (already finished) is ignored */
    }

    color[v] = 2;                  /* finished */
}

int main(int argc, char *argv[])
{
    /* ------------------------------------------------------------------
     *  1.  Validate the command line.
     * ------------------------------------------------------------------ */
    if ((argc - 1) % 2 != 0) {                 /* need an even number of args */
        puts("INVALID_INPUT");
        return 1;
    }

    int n_edges = (argc - 1) / 2;              /* number of (src,dst) pairs   */
    if (n_edges > MAXV) {                      /* the original binary limited the
                                                * number of vertices/edges to 8 */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ------------------------------------------------------------------
     *  2.  Initialise data structures.
     * ------------------------------------------------------------------ */
    memset(adj,   0, sizeof(adj));
    memset(color, 0, sizeof(color));
    found_cycle = false;

    /* ------------------------------------------------------------------
     *  3.  Read the edges.
     * ------------------------------------------------------------------ */
    for (int i = 0; i < n_edges; ++i) {
        char *endptr;
        long src = strtol(argv[1 + 2 * i], &endptr, 10);
        if (*endptr != '\0') {                 /* not a pure integer */
            puts("INVALID_INPUT");
            return 1;
        }
        long dst = strtol(argv[2 + 2 * i], &endptr, 10);
        if (*endptr != '\0') {
            puts("INVALID_INPUT");
            return 1;
        }

        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[(int)src][(int)dst] = 1;           /* store the directed edge */
    }

    /* ------------------------------------------------------------------
     *  4.  Run DFS from every vertex that has not been visited yet.
     * ------------------------------------------------------------------ */
    for (int v = 0; v < MAXV; ++v) {
        if (color[v] == 0)
            dfs(v);
        if (found_cycle)
            break;
    }

    /* ------------------------------------------------------------------
     *  5.  Report the result.
     * ------------------------------------------------------------------ */
    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
